import asyncio
import json
import os
from pydantic_ai import Tool, ModelRetry

_NONINTERACTIVE_ENV = {
    'GIT_TERMINAL_PROMPT': '0',
    'DEBIAN_FRONTEND': 'noninteractive',
    'PYTHONUNBUFFERED': '1',
    'PIP_NO_INPUT': '1',
}

async def run_shell_safe(command: str, cwd: str, timeout: float = 120.0) -> str:
    '''Shell tool with non-interactive env + timeout — prevents LLM from hanging harness.'''
    # Check for shell operators that disqualify auto-run
    _OPERATORS = (';', '&', '|', '>', '<', '`', '$(', '(', '\n', '\r')
    if any(op in command for op in _OPERATORS):
        raise ModelRetry(json.dumps({'error': 'command contains shell operators', 'reason': 'requires user approval'}))
    if timeout > 600:
        timeout = 600  # hard cap at 10 min
    env = {**os.environ, **_NONINTERACTIVE_ENV}
    try:
        proc = await asyncio.create_subprocess_shell(
            command, cwd=cwd, env=env,
            stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.PIPE,
        )
        stdout_b, stderr_b = await asyncio.wait_for(proc.communicate(), timeout=timeout)
        if proc.returncode != 0:
            return f'command failed (exit {proc.returncode}):\n{stderr_b.decode()}'
        return stdout_b.decode()
    except asyncio.TimeoutExpired:
        proc.kill()
        raise ModelRetry(json.dumps({'error': 'command timed out', 'timeout': timeout, 'action': 'refactor into smaller steps or reduce scope'}))
    except Exception as exc:
        raise ModelRetry(json.dumps({'error': str(exc), 'error_type': type(exc).__name__}))

shell_tool = Tool(run_shell_safe, strict=True, timeout=120)
